{"new_string":"def _hand_rank(hand):
    """Return a lexicographically comparable rank for a five-card hand."""
    values = {str(value): value for value in range(2, 11)}
    values.update({"T": 10, "J": 11, "Q": 12, "K": 13, "A": 14})
    cards = hand.split()
    ranks = sorted((values[card[:-1]] for card in cards), reverse=True)
    flush = len({card[-1] for card in cards}) == 1

    straight_high = 0
    if ranks == [14, 5, 4, 3, 2]:
        straight_high = 5
    elif len(set(ranks)) == 5 and ranks[0] - ranks[-1] == 4:
        straight_high = ranks[0]

    # Sort by multiplicity first, then card value, to order all tie-breakers.
    groups = sorted(
        ((ranks.count(rank), rank) for rank in set(ranks)), reverse=True
    )
    counts = [count for count, rank in groups]
    grouped_ranks = tuple(rank for count, rank in groups)

    if flush and straight_high:
        return (8, straight_high)
    if counts == [4, 1]:
        return (7,) + grouped_ranks
    if counts == [3, 2]:
        return (6,) + grouped_ranks
    if flush:
        return (5,) + tuple(ranks)
    if straight_high:
        return (4, straight_high)
    if counts == [3, 1, 1]:
        return (3,) + grouped_ranks
    if counts == [2, 2, 1]:
        return (2,) + grouped_ranks
    if counts == [2, 1, 1, 1]:
        return (1,) + grouped_ranks
    return (0,) + tuple(ranks)


def best_hands(hands):
    """Return all highest-ranking hands in their original input order."""
    winners = []
    best_rank = None
    for hand in hands:
        rank = _hand_rank(hand)
        if best_rank is None or rank > best_rank:
            best_rank = rank
            winners = [hand]
        elif rank == best_rank:
            winners.append(hand)
    return winners
